<template><div class="page"><div class="page-head"><div><h1 class="page-title">图书分类</h1><div class="page-sub">维护图书分类体系和展示顺序</div></div><el-button type="primary" @click="open()"><el-icon><Plus/></el-icon>新增分类</el-button></div><el-card class="table-card"><el-table :data="rows"><el-table-column prop="code" label="分类编码"/><el-table-column prop="name" label="分类名称"/><el-table-column prop="sortNo" label="排序"/><el-table-column label="状态"><template #default><el-tag type="success">启用</el-tag></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="open(row)">编辑</el-button><el-popconfirm title="确定删除吗？" @confirm="remove(row.id)"><template #reference><el-button link type="danger">删除</el-button></template></el-popconfirm></template></el-table-column></el-table></el-card><el-dialog v-model="visible" :title="form.id?'编辑分类':'新增分类'" width="460"><el-form label-position="top"><el-form-item label="分类名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="分类编码"><el-input v-model="form.code"/></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sortNo" :min="0"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template><script setup lang="ts">import{ref,reactive,onMounted}from'vue';import api from'../api';import{ElMessage}from'element-plus';const rows=ref<any[]>([]),visible=ref(false),form=reactive<any>({});onMounted(load);async function load(){rows.value=await api.get('/api/categories')}function open(r:any={}){Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,r,{sortNo:r.sortNo??0,status:1});visible.value=true}async function save(){form.id?await api.put(`/api/categories/${form.id}`,form):await api.post('/api/categories',form);ElMessage.success('保存成功');visible.value=false;load()}async function remove(id:number){await api.delete(`/api/categories/${id}`);load()}</script>

